import{_ as r,c as t,o as n,ag as i}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Note dependency explorer and scheduler","description":"","frontmatter":{},"headers":[],"relativePath":"practice/cs-foundations/dependency-explorer.md","filePath":"practice/cs-foundations/dependency-explorer.md"}'),a={name:"practice/cs-foundations/dependency-explorer.md"};function o(s,e,d,c,l,p){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="note-dependency-explorer-and-scheduler" tabindex="-1">Note dependency explorer and scheduler <a class="header-anchor" href="#note-dependency-explorer-and-scheduler" aria-label="Permalink to “Note dependency explorer and scheduler”">​</a></h1><p><strong>Learner status: still required.</strong> These are two finite in-memory checkpoints, not a production build system. Use the <a href="./#evidence-for-every-checkpoint">shared evidence requirements</a>.</p><h2 id="cs-p05-note-dependency-explorer" tabindex="-1"><span class="hub-section-number">1 </span>CS-P05: note dependency explorer <a class="header-anchor" href="#cs-p05-note-dependency-explorer" aria-label="Permalink to “1 CS-P05: note dependency explorer”">​</a></h2><p><strong>Prerequisites:</strong> CS-P01–04, Map/Set, <a href="./../../cs-foundations/trees-graphs-traversal.html">tree/graph traversal</a>. A note ID is a vertex; a directed link means “can reach this prerequisite/reference.” Reachability is not a safe dependency execution order.</p><p><strong>Scope:</strong> at most 200 vertices/2,000 directed neighbor entries, application-owned data and one chosen start. Implement or reconstruct BFS hop distances, DFS preorder/postorder and separate binary-tree inorder. Unknown JSON requires an explicit parser before typed algorithms. No filesystem crawl or UI is necessary.</p><p><strong>Observable acceptance:</strong></p><ul><li>For a→[b,c], b→[d], c→[d], d→[a], isolated z: BFS a/b/c/d distances 0/1/1/2; DFS preorder a/b/d/c, postorder d/b/c/a; z is absent.</li><li>Self-loop, singleton and disconnected components terminate; each reachable vertex is enqueued once. Neighbor order controls ties, not distance/reachable set.</li><li>Unknown start, missing neighbor, duplicate edge and vertex/edge/ID budget violations reject. Inputs remain unchanged.</li><li>Cross-check distances on exhaustive/generated small directed graphs against an independent all-pairs shortest-hop oracle; compare DFS reachable sets with BFS.</li><li>Null tree gives <code>[]</code>; root2/left1/right3 gives <code>[1,2,3]</code>; non-BST root1/left3/right2 gives <code>[3,1,2]</code>. Reject cycle/shared-child/nonfinite/oversize trees under the reference contract; skewed trees terminate.</li><li>Explain BFS&#39;s layer proof, DFS next-neighbor frame invariant, visited policy, whole-input validation cost and output/frontier/validation storage. State why basic DFS does not detect directed cycles or topologically order the cyclic fixture.</li></ul><p><strong>Failure cases:</strong> marking only after dequeue causing duplicate frontier work; missing visited state on cycles; falsely sorting any tree via inorder; omitting unreachable-invalid adjacency from validation; claiming O(h) total memory despite a visited set/output.</p><p><strong>Evidence:</strong> graph representation/directedness, fixtures, independent oracle/seed, observed orders/distances/rejections, queue/edge counts before timing and mutation checks. Weighted paths, DAG scheduling and cycle classification are optional separate extensions.</p><h2 id="cs-p06-priority-scheduler" tabindex="-1"><span class="hub-section-number">2 </span>CS-P06: priority scheduler <a class="header-anchor" href="#cs-p06-priority-scheduler" aria-label="Permalink to “2 CS-P06: priority scheduler”">​</a></h2><p><strong>Prerequisites:</strong> CS-P04/P05, <a href="./../../cs-foundations/priority-queues.html">heap proof and limitations</a>. This selects work from a finite pending set; graph traversal is not used to pretend all dependencies are executable.</p><p><strong>Scope:</strong> add a stable min-priority queue of at most 200 synthetic note-check jobs. A finite numeric priority is captured on admission; smaller executes first, equal priorities preserve admission order. Drain synchronously under one owner; no network, timers, retries or persistence.</p><p><strong>Observable acceptance:</strong></p><ul><li>After every mixed push/pop, parent ≤ children under <code>(priority,sequence)</code>; peek/pop agree with a separate sorted-list oracle.</li><li>Priorities 2/5/4 then 1 show the documented sift-up/down trace. Equal priorities leave in original order; negative priorities work.</li><li>Empty peek/pop, full push, NaN/infinity and invalid capacity reject without losing existing jobs. Draining returns every admitted job exactly once.</li><li>Input payload identity is preserved; changing a payload&#39;s field does not silently change the captured key. No hidden decrease-key/remove-by-ID promise.</li><li>Explain complete-tree height, O(log n) comparison/swap paths and array-resize amortization separately. Explain why the heap array is not globally sorted and binary search does not apply.</li></ul><p><strong>Failure cases:</strong> promoting the larger child, ignoring the only left child, mishandling the last removal, unstable ties and nonfinite priority comparisons. Explain starvation under continuous high-priority arrivals and why the finite exercise does not establish service fairness or durability.</p><p><strong>Evidence:</strong> deterministic mixed-operation seed, oracle results, heap snapshots/invariant checks, failure/correction, comparison counts and a small selection comparison against repeated full sorting. Use no timing claim without workload/repeated samples.</p>',16)])])}const g=r(a,[["render",o]]);export{u as __pageData,g as default};
